def test_hyb_mgga_xc_mpwkcis1k_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_xc_mpwkcis1k", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.600322116358655e+00, -2.551649876832424e+00, -2.483481314047416e+00, -2.389120130422678e+00, -2.260686520567396e+00, -2.090056771090345e+00, -1.871075472030876e+00, -1.603513305407148e+00, -1.298239866878758e+00, -9.790692295154388e-01, -6.699602604583046e-01, -4.604008773200172e-01, -3.978523835677698e-01, -3.238425869135307e-01, -2.359170454216606e-01, -1.524124106983849e-01, -8.724475092091877e-02, -2.926826440556827e-02, -7.477354380510860e-04, -1.871380403964651e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


